// Sanity-checks `dist/` after a build.
// Astro can emit a silently empty page when a rehype plugin throws, so an
// automated check is the only reliable way to notice.
import fs from 'node:fs';
import path from 'node:path';

const DIST = 'dist';
const SOURCE_DIR = 'docs/posts';
const CATEGORY_SLUGS = {
  Thinkoneering: 'thinkoneering',
  CV: 'cv',
  Publications: 'publications',
};
// URLs the old mkdocs site served that are not generated by a page component.
const EXPECTED_FILES = [
  'robots.txt',
  'feed_rss_created.xml',
  'sitemap-index.xml',
  'autor/index.html',
];

function markdownFiles(directory) {
  return fs.readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const file = path.join(directory, entry.name);
    if (entry.isDirectory()) return markdownFiles(file);
    return entry.isFile() && entry.name.endsWith('.md') ? [file] : [];
  });
}

/** Expected post pages derived from published source content. */
function expectedPosts(root) {
  const sourceRoot = path.join(root, SOURCE_DIR);
  return markdownFiles(sourceRoot)
    .flatMap((sourceFile) => {
      const source = fs.readFileSync(sourceFile, 'utf8');
      const frontmatter = source.match(/^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/)?.[1];
      if (
        !frontmatter ||
        /^draft:[ \t]*true(?:[ \t]+#.*)?[ \t]*$/m.test(frontmatter)
      ) {
        return [];
      }

      const categories = frontmatter.match(
        /^categories:[ \t]*\r?\n((?:[ \t]+-[^\r\n]*\r?\n?)*)/m,
      )?.[1];
      const category = categories
        ?.match(/^[ \t]+-[ \t]*(.+?)[ \t]*$/gm)?.[0]
        ?.replace(/^[ \t]+-[ \t]*/, '')
        .trim();
      const slug = CATEGORY_SLUGS[category];
      if (!slug) return [];

      return [{
        url: `${slug}/${path.basename(sourceFile, '.md')}`,
        source,
      }];
    })
    .sort((a, b) => a.url.localeCompare(b.url));
}

const failures = [];
const posts = expectedPosts('.');
if (posts.length === 0) failures.push('no eligible source posts found');

for (const file of EXPECTED_FILES) {
  if (!fs.existsSync(path.join(DIST, file))) failures.push(`missing ${file}`);
}

for (const post of posts) {
  const { url, source } = post;
  const outputFile = path.join(DIST, url, 'index.html');
  if (!fs.existsSync(outputFile)) {
    failures.push(`missing post page /${url}/`);
    continue;
  }

  const html = fs.readFileSync(outputFile, 'utf8');
  // `<main>` carries Astro's scoped-style attribute, so match it loosely.
  const start = html.search(/<main[\s>]/);
  const body = html.slice(start, html.indexOf('</main>'));
  const sourceBytes = Buffer.byteLength(source);

  if (!/<h1[\s>]/.test(body)) failures.push(`no <h1> in /${url}/`);
  // Catches content dropped by a throwing plugin; rendered HTML is normally
  // larger than its Markdown source, so a third is a generous floor.
  if (body.length < sourceBytes * 0.3) {
    failures.push(
      `content lost in /${url}/ (${body.length}B rendered from ${sourceBytes}B source)`
    );
  }
  if (/\{:[^}]*\}/.test(body)) failures.push(`leftover attr_list in /${url}/`);
  if (/\[-?@[a-zA-Z]/.test(body)) {
    failures.push(`unresolved citation in /${url}/`);
  }
  if (/^\*\[[^\]]+\]:/m.test(body)) {
    failures.push(`leftover abbreviation definition in /${url}/`);
  }
  if (/\[\^\]:/.test(body)) failures.push(`leftover orphan footnote in /${url}/`);
  // citeproc emits this when a numeric style is asked for a narrative citation.
  if (body.includes('NO_PRINTED_FORM')) {
    failures.push(`unrenderable citation in /${url}/`);
  }
  if (
    url === 'thinkoneering/26_04_simplicity_is_complicated' &&
    !html.includes('class="katex"')
  ) {
    failures.push(`math not rendered in /${url}/`);
  }
  // The posts write `word[@key]`, which IEEE would render as `word[1]`. The
  // remark shim inserts the space; this catches it regressing.
  const text = body.replace(/<[^>]+>/g, '');
  const glued = text.match(/[^\s([]\[\d+\]/g);
  if (glued) {
    failures.push(`citation glued to preceding word in /${url}/: ${glued[0]}`);
  }
}

console.log(`checked ${posts.length} expected post pages`);
if (failures.length) {
  for (const f of failures) console.error(`  FAIL  ${f}`);
  process.exit(1);
}
console.log('all checks passed');
